<?php
session_start();if(!isset($_SESSION["studentsid"])){header("Location: ../index.php?msg=Please+log+in+as+Student");exit();}require_once __DIR__.'/../includes/db.php';$db=new db();$db->setconnection();$conn=$db->getConnection();$studentID=$_SESSION["studentsid"];$stmt=$conn->prepare("SELECT studentID,studentName,studentEmail,degree FROM students WHERE studentID=? LIMIT 1");$stmt->bind_param("s",$studentID);$stmt->execute();$student_info=$stmt->get_result()->fetch_assoc();$stmt->close();$db->closeConnection();$msg=$_GET['msg']??'';
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Student Dashboard | LMS</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="dashboard-page"><main class="dashboard-container"><header class="dashboard-header"><div><span class="eyebrow">Library Management System</span><h1>Student Dashboard</h1><p>Search the catalogue and manage your requests.</p></div><a class="logout-link" href="../auth/logout.php">Logout</a></header><?php if($msg!==''):?><div class="alert alert-success"><?php echo htmlspecialchars($msg);?></div><?php endif;?><nav class="dashboard-nav"><button class="nav-btn active" onclick="showSection('student-section',this)">Profile</button><button class="nav-btn" onclick="showSection('search-book-section',this)">Search Book</button><a class="nav-btn" href="bookforrequest.php">My Requests</a></nav><section class="dashboard-card section-panel" id="student-section"><div class="section-heading"><span class="section-icon">01</span><div><h2>Student Details</h2><p>Your registered library account.</p></div></div><?php if($student_info):?><div class="details-grid"><div><span>Student ID</span><strong><?php echo htmlspecialchars($student_info['studentID']);?></strong></div><div><span>Name</span><strong><?php echo htmlspecialchars($student_info['studentName']);?></strong></div><div><span>Email</span><strong><?php echo htmlspecialchars($student_info['studentEmail']);?></strong></div><div><span>Degree</span><strong><?php echo htmlspecialchars(strtoupper($student_info['degree']));?></strong></div></div><?php else:?><div class="alert alert-error">Could not find student details.</div><?php endif;?></section><section class="dashboard-card section-panel" id="search-book-section" hidden><div class="section-heading"><span class="section-icon">02</span><div><h2>Search Book</h2><p>Find books by title.</p></div></div><form method="post" action="searchBook.php" class="dashboard-form"><div class="form-group"><label>Book Name</label><input name="bookName" placeholder="e.g. Computer Networks" required></div><button class="primary-action">Search Catalogue</button></form></section></main><script src="../assets/js/script.js"></script></body></html>